//! NEAR AI provider implementation (Chat Completions API).//!//! This provider uses the OpenAI-compatible Chat Completions endpoint with//! dual auth support://! - **API key auth**: When `NEARAI_API_KEY` is set, uses Bearer API key//! - **Session token auth**: Otherwise, uses `SessionManager` for Bearer session token//!   with automatic renewal on 401 errorsuse std::collections::HashMap;use std::sync::Arc;use async_trait::async_trait;use reqwest::Client;use rust_decimal::Decimal;use rust_decimal::prelude::MathematicalOps;use secrecy::ExposeSecret;use serde::{Deserialize, Serialize};use crate::llm::config::NearAiConfig;use crate::llm::error::LlmError;use crate::llm::provider::{    ChatMessage, CompletionRequest, CompletionResponse, FinishReason, LlmProvider, Role, ToolCall,    ToolCompletionRequest, ToolCompletionResponse,};use crate::llm::{costs, session::SessionManager};/// Information about an available model from NEAR AI API.#[derive(Debug, Clone, Serialize, Deserialize)]pub struct ModelInfo {    /// Model identifier.    #[serde(alias = "id", alias = "model")]    pub name: String,    /// Optional provider name.    #[serde(default)]    pub provider: Option<String>,}/// NEAR AI provider (Chat Completions API, dual auth).pub struct NearAiChatProvider {    client: Client,    config: NearAiConfig,    /// Session manager for session token auth (used when no API key is set).    session: Arc<SessionManager>,    active_model: std::sync::RwLock<String>,    flatten_tool_messages: bool,    /// Per-model pricing fetched from the NEAR AI `/v1/model/list` endpoint.    /// Maps model ID → (input_cost_per_token, output_cost_per_token).    pricing: Arc<std::sync::RwLock<HashMap<String, (Decimal, Decimal)>>>,}impl NearAiChatProvider {    /// Create a new NEAR AI Chat Completions provider.    ///    /// Auth mode is determined by `config.api_key`:    /// - If set, uses Bearer API key auth    /// - If not set, uses session token auth via `SessionManager`    ///    /// By default this enables tool-message flattening for compatibility with    /// providers that reject `role: "tool"` messages.    pub fn new(config: NearAiConfig, session: Arc<SessionManager>) -> Result<Self, LlmError> {        Self::new_with_options(config, session, true, 120)    }    /// Create a new provider with a custom request timeout.    pub fn new_with_timeout(        config: NearAiConfig,        session: Arc<SessionManager>,        request_timeout_secs: u64,    ) -> Result<Self, LlmError> {        Self::new_with_options(config, session, true, request_timeout_secs)    }    /// Create a chat completions provider with configurable tool-message flattening    /// and request timeout.    pub fn new_with_options(        config: NearAiConfig,        session: Arc<SessionManager>,        flatten_tool_messages: bool,        request_timeout_secs: u64,    ) -> Result<Self, LlmError> {        let client = Client::builder()            .timeout(std::time::Duration::from_secs(request_timeout_secs))            .build()            .map_err(|e| LlmError::RequestFailed {                provider: "nearai_chat".to_string(),                reason: format!("Failed to build HTTP client: {}", e),            })?;        let active_model = std::sync::RwLock::new(config.model.clone());        let pricing = Arc::new(std::sync::RwLock::new(HashMap::new()));        let provider = Self {            client,            config,            session,            active_model,            flatten_tool_messages,            pricing,        };        // Fire-and-forget background pricing fetch — don't block startup.        // Only spawns when a tokio runtime is active (skipped in sync tests).        if let Ok(handle) = tokio::runtime::Handle::try_current() {            let client = provider.client.clone();            let base_url = provider.config.base_url.clone();            let api_key = provider.config.api_key.clone();            let session = provider.session.clone();            let pricing = provider.pricing.clone();            handle.spawn(async move {                match fetch_pricing(&client, &base_url, api_key.as_ref(), &session).await {                    Ok(map) if !map.is_empty() => {                        tracing::debug!("Loaded NEAR AI pricing for {} model(s)", map.len());                        match pricing.write() {                            Ok(mut guard) => *guard = map,                            Err(poisoned) => *poisoned.into_inner() = map,                        }                    }                    Ok(_) => {                        tracing::debug!("NEAR AI pricing endpoint returned no pricing data");                    }                    Err(e) => {                        tracing::debug!(                            "Could not fetch NEAR AI pricing (will use fallback): {}",                            e                        );                    }                }            });        }        Ok(provider)    }    fn api_url(&self, path: &str) -> String {        let base = self.config.base_url.trim_end_matches('/');        let path = path.trim_start_matches('/');        if base.ends_with("/v1") {            format!("{}/{}", base, path)        } else {            format!("{}/v1/{}", base, path)        }    }    /// Returns true if using API key auth, false if session token auth.    fn uses_api_key(&self) -> bool {        self.config.api_key.is_some()    }    /// Resolve the Bearer token for the current auth mode.    ///    /// Priority order:    /// 1. `config.api_key` (set at construction from env/config)    /// 2. Session token (OAuth flow)    /// 3. `NEARAI_API_KEY` env var (set by interactive `api_key_login()`)    ///    /// The env var fallback (#3) only triggers after `ensure_authenticated()`    /// runs, because `api_key_login()` sets the env var but not a session token.    async fn resolve_bearer_token(&self) -> Result<String, LlmError> {        // 1. Config-level API key takes priority        if let Some(ref api_key) = self.config.api_key {            return Ok(api_key.expose_secret().to_string());        }        // 2. Existing session token (OAuth was already completed)        if self.session.has_token().await {            let token = self.session.get_token().await?;            return Ok(token.expose_secret().to_string());        }        // No token yet, trigger interactive login        self.session.ensure_authenticated().await?;        // 3. After login, check if a session token was stored (OAuth path)        if self.session.has_token().await {            let token = self.session.get_token().await?;            return Ok(token.expose_secret().to_string());        }        // 4. api_key_login() sets NEARAI_API_KEY env var but not a session token        if let Ok(key) = std::env::var("NEARAI_API_KEY")            && !key.is_empty()        {            return Ok(key);        }        Err(LlmError::AuthFailed {            provider: "nearai".to_string(),        })    }    /// Send a single request to the chat completions API.    ///    /// For session token auth, handles 401 by calling `session.handle_auth_failure()`    /// and retrying once.    ///    /// Does not retry on other errors — retries are handled by the external    /// `RetryProvider` wrapper in the composition chain.    async fn send_request<T: Serialize, R: for<'de> Deserialize<'de>>(        &self,        body: &T,    ) -> Result<R, LlmError> {        match self.send_request_inner(body).await {            Ok(result) => Ok(result),            Err(LlmError::SessionExpired { .. }) if !self.uses_api_key() => {                // Session expired, attempt renewal and retry once                self.session.handle_auth_failure().await?;                self.send_request_inner(body).await            }            Err(e) => Err(e),        }    }    /// Inner request implementation (single attempt).    async fn send_request_inner<T: Serialize, R: for<'de> Deserialize<'de>>(        &self,        body: &T,    ) -> Result<R, LlmError> {        let url = self.api_url("chat/completions");        let token = self.resolve_bearer_token().await?;        tracing::debug!("Sending request to NEAR AI Chat: {}", url);        if tracing::enabled!(tracing::Level::DEBUG)            && let Ok(json) = serde_json::to_string(body)        {            tracing::debug!("NEAR AI Chat request body: {}", json);        }        let response = self            .client            .post(&url)            .header("Authorization", format!("Bearer {}", token))            .header("Content-Type", "application/json")            .json(body)            .send()            .await            .map_err(|e| LlmError::RequestFailed {                provider: "nearai_chat".to_string(),                reason: e.to_string(),            })?;        let status = response.status();        // Extract Retry-After header before consuming the response body.        // Supports both delay-seconds (RFC 7231 §7.1.3) and HTTP-date formats.        let retry_after_header = response            .headers()            .get("retry-after")            .and_then(|v| v.to_str().ok())            .and_then(|v| {                // Try delay-seconds first (most common from API providers)                if let Ok(secs) = v.trim().parse::<u64>() {                    return Some(std::time::Duration::from_secs(secs));                }                // Try HTTP-date (e.g. "Mon, 02 Mar 2026 18:00:00 GMT")                if let Ok(dt) = chrono::DateTime::parse_from_rfc2822(v.trim()) {                    let now = chrono::Utc::now();                    let delta = dt.signed_duration_since(now);                    // Use max(0) so past/present dates yield Duration::ZERO                    // rather than None (which would cause an immediate retry).                    return Some(std::time::Duration::from_secs(                        delta.num_seconds().max(0) as u64                    ));                }                None            });        let response_text = response.text().await.map_err(|e| LlmError::RequestFailed {            provider: "nearai_chat".to_string(),            reason: format!("Failed to read response body: {}", e),        })?;        // Log response body only at TRACE level to avoid exposing sensitive content        // (user-generated data, tool outputs, leaked secrets) in DEBUG logs        if tracing::enabled!(tracing::Level::TRACE) {            tracing::trace!("NEAR AI Chat response body: {}", response_text);        }        if !status.is_success() {            let status_code = status.as_u16();            if status_code == 401 {                // For session token auth, distinguish session expired from plain auth failure                if !self.uses_api_key() {                    let lower = response_text.to_lowercase();                    let is_session_expired = lower.contains("session")                        && (lower.contains("expired") || lower.contains("invalid"));                    if is_session_expired {                        return Err(LlmError::SessionExpired {                            provider: "nearai_chat".to_string(),                        });                    }                }                return Err(LlmError::AuthFailed {                    provider: "nearai_chat".to_string(),                });            }            if status_code == 429 {                return Err(LlmError::RateLimited {                    provider: "nearai_chat".to_string(),                    retry_after: retry_after_header,                });            }            let truncated = crate::agent::truncate_for_preview(&response_text, 512);            return Err(LlmError::RequestFailed {                provider: "nearai_chat".to_string(),                reason: format!("HTTP {}: {}", status, truncated),            });        }        serde_json::from_str(&response_text).map_err(|e| {            let truncated = crate::agent::truncate_for_preview(&response_text, 512);            LlmError::InvalidResponse {                provider: "nearai_chat".to_string(),                reason: format!("JSON parse error: {}. Raw: {}", e, truncated),            }        })    }    /// Fetch available models from the NEAR AI API.    ///    /// Handles session renewal on 401 (same pattern as `send_request`).    /// Supports multiple response formats: `{models: [...]}`, `{data: [...]}`, and plain array.    pub async fn list_models_full(&self) -> Result<Vec<ModelInfo>, LlmError> {        match self.list_models_inner().await {            Ok(models) => Ok(models),            Err(LlmError::SessionExpired { .. }) if !self.uses_api_key() => {                self.session.handle_auth_failure().await?;                self.list_models_inner().await            }            Err(e) => Err(e),        }    }    async fn list_models_inner(&self) -> Result<Vec<ModelInfo>, LlmError> {        let url = self.api_url("models");        let token = self.resolve_bearer_token().await?;        tracing::debug!("Fetching models from: {}", url);        let response = self            .client            .get(&url)            .header("Authorization", format!("Bearer {}", token))            .send()            .await            .map_err(|e| LlmError::RequestFailed {                provider: "nearai_chat".to_string(),                reason: format!("Failed to fetch models: {}", e),            })?;        let status = response.status();        let response_text = response.text().await.map_err(|e| LlmError::RequestFailed {            provider: "nearai_chat".to_string(),            reason: format!("Failed to read response body: {}", e),        })?;        if !status.is_success() {            if status.as_u16() == 401 && !self.uses_api_key() {                return Err(LlmError::SessionExpired {                    provider: "nearai_chat".to_string(),                });            }            let truncated = crate::agent::truncate_for_preview(&response_text, 512);            return Err(LlmError::RequestFailed {                provider: "nearai_chat".to_string(),                reason: format!("HTTP {}: {}", status, truncated),            });        }        // Flexible model entry parsing -- handle various field names        #[derive(Deserialize)]        struct ModelMetadataInner {            #[serde(default)]            name: Option<String>,            #[serde(default, alias = "modelName", alias = "model_name")]            model_name: Option<String>,        }        #[derive(Deserialize)]        struct ModelEntry {            #[serde(default)]            name: Option<String>,            #[serde(default)]            id: Option<String>,            #[serde(default)]            model: Option<String>,            #[serde(default, alias = "modelName", alias = "model_name")]            model_name: Option<String>,            #[serde(default, alias = "modelId", alias = "model_id")]            model_id: Option<String>,            #[serde(default)]            metadata: Option<ModelMetadataInner>,        }        impl ModelEntry {            fn get_name(&self) -> Option<String> {                self.name                    .clone()                    .or_else(|| self.id.clone())                    .or_else(|| self.model.clone())                    .or_else(|| self.model_name.clone())                    .or_else(|| self.model_id.clone())                    .or_else(|| self.metadata.as_ref().and_then(|m| m.name.clone()))                    .or_else(|| self.metadata.as_ref().and_then(|m| m.model_name.clone()))            }        }        #[derive(Deserialize)]        struct ModelsResponse {            #[serde(default)]            models: Option<Vec<ModelEntry>>,            #[serde(default)]            data: Option<Vec<ModelEntry>>,        }        // Try {models: [...]} or {data: [...]} format        if let Ok(resp) = serde_json::from_str::<ModelsResponse>(&response_text)            && let Some(entries) = resp.models.or(resp.data)        {            let models: Vec<ModelInfo> = entries                .into_iter()                .filter_map(|e| {                    e.get_name().map(|name| ModelInfo {                        name,                        provider: None,                    })                })                .collect();            if !models.is_empty() {                return Ok(models);            }        }        // Try direct array format        if let Ok(entries) = serde_json::from_str::<Vec<ModelEntry>>(&response_text) {            let models: Vec<ModelInfo> = entries                .into_iter()                .filter_map(|e| {                    e.get_name().map(|name| ModelInfo {                        name,                        provider: None,                    })                })                .collect();            if !models.is_empty() {                return Ok(models);            }        }        // Couldn't find model names in response        Err(LlmError::InvalidResponse {            provider: "nearai_chat".to_string(),            reason: format!(                "No model names found in response: {}",                &response_text[..response_text.len().min(300)]            ),        })    }}#[async_trait]impl LlmProvider for NearAiChatProvider {    async fn complete(&self, req: CompletionRequest) -> Result<CompletionResponse, LlmError> {        let model = req.model.unwrap_or_else(|| self.active_model_name());        let mut raw_messages = req.messages;        crate::llm::provider::sanitize_tool_messages(&mut raw_messages);        let messages: Vec<ChatCompletionMessage> =            raw_messages.into_iter().map(|m| m.into()).collect();        let request = ChatCompletionRequest {            model,            messages,            temperature: req.temperature,            max_tokens: req.max_tokens,            stop: req.stop_sequences,            tools: None,            tool_choice: None,        };        let response: ChatCompletionResponse = self.send_request(&request).await?;        let choice =            response                .choices                .into_iter()                .next()                .ok_or_else(|| LlmError::InvalidResponse {                    provider: "nearai_chat".to_string(),                    reason: "No choices in response".to_string(),                })?;        // Fall back to reasoning_content when content is null (same as        // complete_with_tools — reasoning models may put the answer there).        let content = choice            .message            .content            .or(choice.message.reasoning_content)            .unwrap_or_default();        let finish_reason = match choice.finish_reason.as_deref() {            Some("stop") => FinishReason::Stop,            Some("length") => FinishReason::Length,            Some("tool_calls") => FinishReason::ToolUse,            Some("content_filter") => FinishReason::ContentFilter,            _ => FinishReason::Unknown,        };        let (input_tokens, output_tokens) = parse_usage(response.usage.as_ref());        Ok(CompletionResponse {            content,            finish_reason,            input_tokens,            output_tokens,            cache_read_input_tokens: 0,            cache_creation_input_tokens: 0,        })    }    async fn complete_with_tools(        &self,        req: ToolCompletionRequest,    ) -> Result<ToolCompletionResponse, LlmError> {        let model = req.model.unwrap_or_else(|| self.active_model_name());        let mut raw_messages = req.messages;        crate::llm::provider::sanitize_tool_messages(&mut raw_messages);        let messages: Vec<ChatCompletionMessage> =            raw_messages.into_iter().map(|m| m.into()).collect();        // Some OpenAI-compatible providers reject `role:"tool"` messages.        // When enabled, rewrite tool-call / tool-result pairs into plain text.        let messages = if self.flatten_tool_messages {            flatten_tool_messages(messages)        } else {            messages        };        let tools: Vec<ChatCompletionTool> = req            .tools            .into_iter()            .map(|t| ChatCompletionTool {                tool_type: "function".to_string(),                function: ChatCompletionFunction {                    name: t.name,                    description: Some(t.description),                    parameters: Some(t.parameters),                },            })            .collect();        let request = ChatCompletionRequest {            model,            messages,            temperature: req.temperature,            max_tokens: req.max_tokens,            stop: req.stop_sequences,            tools: if tools.is_empty() { None } else { Some(tools) },            tool_choice: req.tool_choice,        };        let response: ChatCompletionResponse = self.send_request(&request).await?;        let choice =            response                .choices                .into_iter()                .next()                .ok_or_else(|| LlmError::InvalidResponse {                    provider: "nearai_chat".to_string(),                    reason: "No choices in response".to_string(),                })?;        let tool_calls: Vec<ToolCall> = choice            .message            .tool_calls            .unwrap_or_default()            .into_iter()            .map(|tc| {                let arguments = serde_json::from_str(&tc.function.arguments)                    .unwrap_or(serde_json::Value::Object(Default::default()));                ToolCall {                    id: tc.id,                    name: tc.function.name,                    arguments,                }            })            .collect();        // Fall back to reasoning_content when content is null (e.g. GLM-5        // returns its answer in reasoning_content instead of content), but        // only for final text responses. Tool-call responses often have        // content: null + reasoning_content filled with chain-of-thought;        // leaking that into conversation history inflates context and        // confuses the model.        let content = if tool_calls.is_empty() {            choice.message.content.or(choice.message.reasoning_content)        } else {            choice.message.content        };        let finish_reason = match choice.finish_reason.as_deref() {            Some("stop") => FinishReason::Stop,            Some("length") => FinishReason::Length,            Some("tool_calls") => FinishReason::ToolUse,            Some("content_filter") => FinishReason::ContentFilter,            _ => {                if !tool_calls.is_empty() {                    FinishReason::ToolUse                } else {                    FinishReason::Unknown                }            }        };        let (input_tokens, output_tokens) = parse_usage(response.usage.as_ref());        Ok(ToolCompletionResponse {            content,            tool_calls,            finish_reason,            input_tokens,            output_tokens,            cache_read_input_tokens: 0,            cache_creation_input_tokens: 0,        })    }    fn model_name(&self) -> &str {        &self.config.model    }    fn cost_per_token(&self) -> (Decimal, Decimal) {        let model = self.active_model_name();        // Try fetched pricing first, then static lookup table, then default        if let Ok(guard) = self.pricing.read()            && let Some(&rates) = guard.get(&model)        {            return rates;        }        costs::model_cost(&model).unwrap_or_else(costs::default_cost)    }    async fn list_models(&self) -> Result<Vec<String>, LlmError> {        let models = self.list_models_full().await?;        Ok(models.into_iter().map(|m| m.name).collect())    }    fn active_model_name(&self) -> String {        match self.active_model.read() {            Ok(guard) => guard.clone(),            Err(poisoned) => {                tracing::warn!("active_model lock poisoned while reading; continuing");                poisoned.into_inner().clone()            }        }    }    fn set_model(&self, model: &str) -> Result<(), crate::error::LlmError> {        match self.active_model.write() {            Ok(mut guard) => {                *guard = model.to_string();            }            Err(poisoned) => {                tracing::warn!("active_model lock poisoned while writing; continuing");                *poisoned.into_inner() = model.to_string();            }        }        Ok(())    }}// OpenAI-compatible Chat Completions API types#[derive(Debug, Serialize)]struct ChatCompletionRequest {    model: String,    messages: Vec<ChatCompletionMessage>,    #[serde(skip_serializing_if = "Option::is_none")]    temperature: Option<f32>,    #[serde(skip_serializing_if = "Option::is_none")]    max_tokens: Option<u32>,    #[serde(skip_serializing_if = "Option::is_none")]    stop: Option<Vec<String>>,    #[serde(skip_serializing_if = "Option::is_none")]    tools: Option<Vec<ChatCompletionTool>>,    #[serde(skip_serializing_if = "Option::is_none")]    tool_choice: Option<String>,}/// Content field that serializes as either a string or an array of content parts.////// - `Text("hello")` → `"content": "hello"`/// - `Parts([...])` → `"content": [{"type": "text", ...}, {"type": "image_url", ...}]`#[derive(Debug, Clone)]enum MessageContent {    Text(String),    Parts(Vec<crate::llm::ContentPart>),}impl Serialize for MessageContent {    fn serialize<S: serde::Serializer>(&self, serializer: S) -> Result<S::Ok, S::Error> {        match self {            MessageContent::Text(s) => serializer.serialize_str(s),            MessageContent::Parts(parts) => parts.serialize(serializer),        }    }}impl<'de> Deserialize<'de> for MessageContent {    fn deserialize<D: serde::Deserializer<'de>>(deserializer: D) -> Result<Self, D::Error> {        use serde::de;        use serde_json::Value;        let val = Value::deserialize(deserializer)?;        match val {            Value::String(s) => Ok(MessageContent::Text(s)),            Value::Array(arr) => Ok(MessageContent::Text(                // For deserialization (responses), we only need the text content                arr.iter()                    .find_map(|v| {                        if v.get("type")?.as_str()? == "text" {                            v.get("text")?.as_str().map(String::from)                        } else {                            None                        }                    })                    .unwrap_or_default(),            )),            Value::Null => Ok(MessageContent::Text(String::new())),            _ => Err(de::Error::custom(                "expected string, array, or null for content",            )),        }    }}impl MessageContent {    fn as_text(&self) -> Option<&str> {        match self {            MessageContent::Text(s) if !s.is_empty() => Some(s),            MessageContent::Text(_) => None,            MessageContent::Parts(_) => None,        }    }}#[derive(Debug, Serialize, Deserialize)]struct ChatCompletionMessage {    role: String,    #[serde(skip_serializing_if = "Option::is_none")]    content: Option<MessageContent>,    #[serde(skip_serializing_if = "Option::is_none")]    tool_call_id: Option<String>,    #[serde(skip_serializing_if = "Option::is_none")]    name: Option<String>,    #[serde(skip_serializing_if = "Option::is_none")]    tool_calls: Option<Vec<ChatCompletionToolCall>>,}// -- Pricing fetch types and logic -----------------------------------------/// Cost amount from the NEAR AI `/v1/model/list` response.////// Real cost per token = `amount * 10^(-scale)`.#[derive(Debug, Deserialize)]struct ModelCost {    amount: f64,    #[serde(default)]    scale: i32,}/// A single model entry from the pricing response.#[derive(Debug, Deserialize)]struct PricingModelEntry {    #[serde(default, alias = "modelId", alias = "model_id")]    model_id: Option<String>,    #[serde(default, alias = "inputCostPerToken")]    input_cost_per_token: Option<ModelCost>,    #[serde(default, alias = "outputCostPerToken")]    output_cost_per_token: Option<ModelCost>,    #[serde(default)]    metadata: Option<PricingMetadata>,}#[derive(Debug, Deserialize)]struct PricingMetadata {    #[serde(default)]    aliases: Vec<String>,}/// Wrapper for the `/v1/model/list` response body.#[derive(Debug, Deserialize)]struct PricingResponse {    #[serde(default)]    models: Option<Vec<PricingModelEntry>>,    #[serde(default)]    data: Option<Vec<PricingModelEntry>>,}/// Convert a `ModelCost` to a `Decimal` per-token price.fn model_cost_to_decimal(mc: &ModelCost) -> Option<Decimal> {    if mc.amount == 0.0 {        return Some(Decimal::ZERO);    }    // amount * 10^(-scale)    let base = Decimal::try_from(mc.amount).ok()?;    let factor = Decimal::TEN.checked_powi(-i64::from(mc.scale))?;    base.checked_mul(factor)}/// Fetch pricing from the NEAR AI `/v1/model/list` endpoint.////// Returns a map of model_id → (input_cost_per_token, output_cost_per_token)./// Errors are non-fatal; callers should fall back to the static lookup table.